node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Search for the product
const rows = db.prepare(\"SELECT * FROM products WHERE name LIKE '%M310%' OR name LIKE '%Wireless Mouse%' OR product_id LIKE '%FA0948%'\").all();
console.log('Products found:', rows.length);
for (const r of rows) {
  console.log(JSON.stringify(r, null, 2));
}
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Check rt_variants for this product
const variants = db.prepare(\"SELECT * FROM rt_variants WHERE product_id = 'PROD-FA0948'\").all();
console.log('rt_variants for PROD-FA0948:', JSON.stringify(variants, null, 2));

// Also check compatible products
const compat = ['PROD-B98D14','PROD-2DBA15','PROD-7C0240','PROD-73FAB4'];
for (const pid of compat) {
  const p = db.prepare('SELECT product_id, name, brand, category, subcategory FROM products WHERE product_id = ?').get(pid);
  if (p) console.log('Compatible:', JSON.stringify(p));
}
"

